#include <stdio.h>
int main() {
    int a = 29;
    int b = 24;
    int c = 21;
    printf("expr1: %d\n", a + b * c);
    printf("expr2: %d\n", (a + b) * c);
    printf("expr3: %d\n", a * b / c);
    printf("expr4: %d\n", a - b - c);
    printf("expr5: %d\n", a + (b - c) * a);
    return 0;
}
